"""PE parser regression tests using generated bytes, not an installed client."""

import importlib.util
from pathlib import Path
import struct
import tempfile
import unittest


SCRIPT = Path(__file__).resolve().parents[1] / "scripts/inspect_weixin.py"
SPEC = importlib.util.spec_from_file_location("inspect_weixin", SCRIPT)
INSPECTOR = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(INSPECTOR)


def synthetic_pe():
    data = bytearray(0xA00)
    data[:2] = b"MZ"
    struct.pack_into("<I", data, 0x3C, 0x80)
    data[0x80:0x84] = b"PE\0\0"
    struct.pack_into("<HHIIIHH", data, 0x84, 0x8664, 2, 0, 0, 0, 240, 0x2022)
    optional = 0x98
    struct.pack_into("<H", data, optional, 0x20B)
    struct.pack_into("<I", data, optional + 16, 0x1000)
    struct.pack_into("<Q", data, optional + 24, 0x180000000)
    struct.pack_into("<II", data, optional + 32, 0x1000, 0x200)
    struct.pack_into("<II", data, optional + 56, 0x3000, 0x400)
    struct.pack_into("<I", data, optional + 108, 16)
    struct.pack_into("<II", data, optional + 112, 0x2000, 0x100)
    struct.pack_into("<II", data, optional + 112 + 2 * 8, 0x2200, 0x200)
    for index, (name, virtual, rva, raw_size, raw, flags) in enumerate((
            (b".text", 0x300, 0x1000, 0x200, 0x400, 0x60000020),
            (b".rdata", 0x400, 0x2000, 0x400, 0x600, 0x40000040))):
        pos = optional + 240 + index * 40
        data[pos:pos + len(name)] = name
        struct.pack_into("<IIII", data, pos + 8, virtual, rva, raw_size, raw)
        struct.pack_into("<I", data, pos + 36, flags)
    # Two exports: a normal function and a forwarded symbol.
    struct.pack_into("<IIHHIIIIIII", data, 0x600, 0, 0, 0, 0, 0x2040, 1, 2, 2,
                     0x2060, 0x2068, 0x2070)
    data[0x640:0x64B] = b"sample.dll\0"
    struct.pack_into("<II", data, 0x660, 0x1000, 0x2080)
    struct.pack_into("<II", data, 0x668, 0x2090, 0x2098)
    struct.pack_into("<HH", data, 0x670, 0, 1)
    data[0x680:0x68C] = b"OTHER.entry\0"
    data[0x690:0x696] = b"FnOne\0"
    data[0x698:0x69E] = b"FnTwo\0"
    # One RT_VERSION tree and VS_FIXEDFILEINFO record.
    for position, name, child in ((0x800, 16, 0x80000018),
                                  (0x818, 1, 0x80000030), (0x830, 2052, 0x48)):
        struct.pack_into("<HH", data, position + 12, 0, 1)
        struct.pack_into("<II", data, position + 16, name, child)
    struct.pack_into("<IIII", data, 0x848, 0x2260, 92, 0, 0)
    struct.pack_into("<HHH", data, 0x860, 92, 52, 0)
    key = "VS_VERSION_INFO\0".encode("utf-16-le")
    data[0x866:0x866 + len(key)] = key
    struct.pack_into("<13I", data, 0x888, 0xFEEF04BD, 0x10000,
                     0x40001, 0xF000D, 0x40001, 0xF000D, 0, 0, 0, 0, 0, 0, 0)
    return data


class PEInspectionTests(unittest.TestCase):
    def test_sections_exports_and_version(self):
        pe = INSPECTOR.PE(synthetic_pe())
        self.assertEqual(pe.header["architecture"], "x86-64")
        self.assertEqual(pe.map_rva(0x1000)["file_offset"], 0x400)
        self.assertEqual(pe.map_rva(0x1250)["status"], "zero_fill")
        self.assertEqual(pe.map_rva(0x20)["status"], "headers")
        self.assertEqual(pe.map_rva(0x4000)["status"], "unmapped")
        self.assertEqual(pe.exports()["entries"][0]["names"], ["FnOne"])
        self.assertEqual(pe.exports()["entries"][1]["forwarder"], "OTHER.entry")
        self.assertEqual(pe.file_versions()[0]["file_version"], "4.1.15.13")
        self.assertEqual(pe.header["data_directories"][4]["address_kind"], "file_offset")

    def test_rejects_truncated_and_invalid_address_tables(self):
        with self.assertRaises(INSPECTOR.PEError):
            INSPECTOR.PE(b"MZ")
        data = synthetic_pe()
        struct.pack_into("<I", data, 0x98 + 240 + 16, 0xFFFFFFF0)
        with self.assertRaises(INSPECTOR.PEError):
            INSPECTOR.PE(data)
        data = synthetic_pe()
        struct.pack_into("<H", data, 0x670, 12)
        with self.assertRaises(INSPECTOR.PEError):
            INSPECTOR.PE(data).exports()

    def test_legacy_roles_and_bounded_non_executable_string_search(self):
        data = synthetic_pe()
        data[0x400:0x407] = b"Needle\0"  # Executable data is intentionally outside the string search.
        data[0x700:0x707] = b"Needle\0"
        data[0x710:0x717] = b"Needle\0"
        pe = INSPECTOR.PE(data)
        result = INSPECTOR.string_candidates(pe, ["Needle"], 1)[0]
        self.assertEqual(result["matches"][0]["file_offset"], 0x700)
        self.assertTrue(result["more_matches_exist"])
        with tempfile.TemporaryDirectory(prefix="wxhelper-pe-test-") as directory:
            source = Path(directory) / "offsets.h"
            source.write_text("const UINT64 kMicroMsgDB = 0xb8;\n"
                              "const UINT64 kSendTextMsg = 0x1000;\n", encoding="utf-8")
            mappings = INSPECTOR.legacy_constants(source, pe, 8)
        self.assertEqual(mappings[0]["source_role"], "structure_field_offset")
        self.assertEqual(mappings[1]["source_role"], "function_rva")
        self.assertEqual(mappings[1]["sample_bytes_hex"], "4e 65 65 64 6c 65 00 00")


if __name__ == "__main__":
    unittest.main()
